+        this.label = label;
+    }
+
+    public String name() {
+        return name;
+    }
+
+    /** Collect the value of a raw field  */
+    @Override
+    public void collect(Object value) {
+        label.collect(value);
+        isEmpty = false;
+    }
+
+    public Label label() {
+        return this.label;
+    }
+
+    public void reset() {
+        label.reset();
+        isEmpty = true;
+    }
+
+    /**
