+                        scratchTransactionBytesStreamOutput.reset();
+                        for (Long l : itemBuffer) {
+                            scratchTransactionBytesStreamOutput.writeVLong(l);
+                        }
+
+                        long newId = prunedTransactions.add(scratchTransactionBytesStreamOutput.get());
