+        super(bigArrays);
+
+        this.items = items;
+        this.itemCounts = itemCounts;
+        this.totalItemCount = totalItemCount;
+        this.transactions = transactions;
+        this.transactionCounts = transactionCounts;
+        this.totalTransactionCount = totalTransactionCount;
+    }
