+            if (item == ids.longs[ids.length - itemsLeft]) {
+                --itemsLeft;
+                if (itemsLeft == 0) {
+                    return true;
+                }
+            }
+        }
+
+        return false;
+    }
+
+    @Override
+    public long ramBytesUsed() {
+        return BASE_RAM_BYTES_USED + scratchBytesRef.length + scratchByteArrayStreamInput.length();
+    }
