+                    new DelimitedToken.Encoded(
+                        whitespaceToken.charSequence().toString(),
+                        Objects.requireNonNullElse(maybeTokenized, unknownTokenId),
+                        correctOffset(whitespaceToken.startOffset()),
+                        correctOffset(whitespaceToken.endOffset())
